-- Allow nine more local drafts (service proposals, agreement, invoice, client portal, project board; education certificate, course sales page, coaching program, workshop plan) in the same revisioned, owner-write, member-read draft store.
alter table public.launcher_drafts drop constraint launcher_drafts_kind_check;
alter table public.launcher_drafts add constraint launcher_drafts_kind_check check (kind in ('skill-assessment','market-evidence','offer-validation','pricing-scenario','brand-direction','business-plan','crm-contacts','crm-pipeline','lead-forms','storefront','link-in-bio','ad-concepts','community-space','website-page','service-proposals','service-agreement','service-invoice','service-portal','service-projects','education-certificate','education-sales-page','education-coaching','education-workshop'));
